const envelope = ($input.first().json || {}).body || $input.first().json || {};
const request = envelope.normalized_github_execution_request_json || {};
const errors = [];
if (envelope.github_execution_request_json) errors.push('raw_github_execution_request_json_forbidden');
if (!(envelope.accepted === true && envelope.validation_status === 'pass')) errors.push('validated_normalized_github_execution_request_required');
if (request.repository_full_name !== 'Viktoryyyyy/moex-robot') errors.push('repository_full_name_not_allowed');
if (request.base_ref !== 'origin/main') errors.push('base_ref_must_equal_origin_main');
if (!/^[0-9a-f]{40}$/i.test(String(request.base_sha || ''))) errors.push('valid_base_sha_required');
if (!String(request.branch_name || '').startsWith('n8n/')) errors.push('branch_name_must_use_n8n_prefix');
if (String(request.branch_name || '').startsWith('route-b/') || ['main','master','refs/heads/main','refs/heads/master'].includes(String(request.branch_name || '').toLowerCase())) errors.push('branch_name_forbidden');
if (!String(request.execution_request_id || '').trim()) errors.push('execution_request_id_required');
if (!String(request.workflow_run_id || '').trim()) errors.push('workflow_run_id_required');
if (!String(request.role_task_id || '').trim()) errors.push('role_task_id_required');
if (!/^[0-9a-f]{64}$/i.test(String(request.request_fingerprint_sha256 || ''))) errors.push('request_fingerprint_sha256_required');
if (request.execution_request_id === request.task_id) errors.push('execution_request_id_task_id_fallback_forbidden');
if (request.merge_authority !== 'PM_L2_ONLY') errors.push('merge_authority_must_equal_PM_L2_ONLY');
for (const control of ['direct_main_write_allowed','force_push_allowed','file_delete_allowed','n8n_merge_allowed','executor_merge_allowed','server_apply_allowed','broker_execution_allowed','live_trading_allowed','runtime_allowed','production_secret_access_allowed','pm_l2_approval_claimed']) {
  if (request[control] !== false) errors.push(control + '_must_be_false');
}
const approvedFileScope = Array.isArray(request.approved_file_scope) ? request.approved_file_scope : [];
const fileChanges = Array.isArray(request.file_changes) ? request.file_changes : [];
if (approvedFileScope.length === 0) errors.push('approved_file_scope_must_not_be_empty');
if (fileChanges.length === 0) errors.push('exact_file_changes_required');
if (approvedFileScope.length !== fileChanges.length) errors.push('file_change_count_must_equal_approved_file_scope');
for (const change of fileChanges) {
  if (!approvedFileScope.includes(change.path)) errors.push('file_change_path_must_equal_approved_file_scope');
  if (!['create','update'].includes(String(change.operation || '').toLowerCase())) errors.push('file_change_operation_must_be_create_or_update');
}
if (errors.length) throw new Error(errors.join('|'));
return [{json:{...request, approved_for_merge: false, merge_performed: false}}];

const request = $node['Validate Normalized Runtime Request'].json;
const event_rows = $('Load Execution Evidence Registry').all().map((item) => item.json || {});
const existing_result = event_rows.find((row) => String((row.event_payload_json || {}).request_fingerprint_sha256 || '') === request.request_fingerprint_sha256) || null;
const commit_step = 'create_implementation_commit';
const pr_step = 'open_pull_request';
if (event_rows.find((row) => String((row.event_payload_json || {}).request_fingerprint_sha256 || '') && String((row.event_payload_json || {}).request_fingerprint_sha256 || '') !== request.request_fingerprint_sha256)) {
  return [{json:{...request, resolution: 'blocked', blocker_code: 'same_execution_request_id_different_fingerprint', existing_result: null, approved_for_merge: false, merge_performed: false}}];
}
if (existing_result) {
  return [{json:{...request, resolution: 'return_existing_result', existing_result, approved_for_merge: false, merge_performed: false}}];
}
if (request.resume_from === commit_step || request.resume_from === pr_step) {
  return [{json:{...request, resolution: 'resume_or_return_existing_result', existing_result: {implementation_commit_sha: null, pr_number: null, pr_url: null}, approved_for_merge: false, merge_performed: false}}];
}
return [{json:{...request, resolution: 'proceed_new_execution', existing_result: null, approved_for_merge: false, merge_performed: false}}];

const request = $node['Validate Normalized Runtime Request'].json;
const ref = $node['Fetch Base Branch Ref'].json || {};
const commit = $node['Fetch Base Commit'].json || {};
if (!ref.object || ref.object.sha !== request.base_sha) throw new Error('base_sha_not_current_main');
if (!commit.tree || !commit.tree.sha) throw new Error('missing_base_tree_sha');
return [{json:{...request, base_tree_sha: commit.tree.sha}}];

const request = $node['Validate Base Ref'].json;
const tree_elements = request.file_changes.map((change) => ({
  path: change.path,
  content: change.content,
  type: 'blob',
  mode: '100644',
}));
return [{json:{...request, tree_elements}}];

const request = $node['Validate Base Ref'].json;
const pr = $node['Open Pull Request'].json || {};
const commit = $node['Create Implementation Commit'].json || {};
return [{json:{
  execution_request_id: request.execution_request_id,
  request_fingerprint_sha256: request.request_fingerprint_sha256,
  implementation_commit_sha: commit.sha || null,
  pr_number: pr.number || null,
  pr_url: pr.html_url || pr.url || null,
  pr_head_sha: commit.sha || null,
  ci_workflow: 'tests',
  approved_for_merge: false,
  merge_performed: false,
  github_mutation_performed: Boolean(commit.sha || pr.number),
}}];
